// NewGenerateSSEEventOK builds a "tabular" service "generate" endpoint result
// from a HTTP "OK" response.
func NewGenerateSSEEventOK(body *GenerateResponseBody) *tabular.SSEEvent {
	v := &tabular.SSEEvent{
		Type:    *body.Type,
		Text:    body.Text,
		Message: body.Message,
		Data:    body.Data,
		Error:   body.Error,
	}
	if body.Event != nil {
		v.Event = unmarshalAssistantEventResponseBodyToTabularAssistantEvent(body.Event)
	}
	if body.Cell != nil {
		v.Cell = unmarshalTabularCellResponseBodyToTabularTabularCell(body.Cell)
	}
	if body.Annotations != nil {
		v.Annotations = make([]*tabular.CitationAnnotation, len(body.Annotations))
		for i, val := range body.Annotations {
			if val == nil {
				v.Annotations[i] = nil
				continue
			}
			v.Annotations[i] = unmarshalCitationAnnotationResponseBodyToTabularCitationAnnotation(val)
		}
	}

	return v
}

